const numeroInput=document.getElementById("phone_number");function createSMS(){const e=window.location.pathname.includes("main_en"),t=document.getElementById("bank").value,n=document.getElementById("phone_number").value.replace(/-/g,""),o=document.getElementById("amount").value,l=document.getElementById("details").value;if(!(t&&n&&o&&l))return c=e?"Please complete all fields.":"Por favor completa todos los campos.",void alert(c);const a=`sms:${t}?&body=${encodeURIComponent(`Pase ${o} ${n} ${l}`)}`;console.log(a);const c=e?"Message generated successfully.":"Mensaje generado con éxito.";alert(c),window.location.href=".../../checkpages/success.html"}numeroInput.addEventListener("input",(function(e){let t=e.target.value.replace(/\D/g,"");t.length>4&&(t=t.slice(0,4)+"-"+t.slice(4,8)),e.target.value=t})),document.addEventListener("DOMContentLoaded",(()=>{document.getElementById("year").textContent=(new Date).getFullYear()})),document.addEventListener("contextmenu",(function(e){e.preventDefault()})),document.addEventListener("keydown",(function(e){"F12"===e.key&&e.preventDefault(),e.ctrlKey&&e.shiftKey&&("I"===e.key||"J"===e.key)&&e.preventDefault(),e.ctrlKey&&"u"===e.key&&e.preventDefault(),e.ctrlKey&&"s"===e.key&&e.preventDefault()}));